package org.roadwatch.service;
import org.roadwatch.model.Models.*;import org.roadwatch.repo.*;import org.roadwatch.storage.PhotoStorage;import org.springframework.beans.factory.annotation.Value;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import org.springframework.web.multipart.MultipartFile;import org.springframework.web.client.RestClient;import java.time.Instant;import java.util.*;import java.io.IOException;
@Service public class ReportService {
 private final ReportRepository reports; private final IssueRepository issues; private final AuditRepository audits; private final PhotoStorage storage; private final RestClient ml;
 @Value("${roadwatch.duplicate-radius-meters:30}") double radius;
 public ReportService(ReportRepository r,IssueRepository i,AuditRepository a,PhotoStorage storage,@Value("${roadwatch.ml-url}") String mlUrl){reports=r;issues=i;audits=a;this.storage=storage;ml=RestClient.builder().baseUrl(mlUrl).build();}
 public record Detection(@com.fasterxml.jackson.annotation.JsonProperty("class") String type,double confidence,List<Double> bbox){} public record MlResult(List<Detection> detections,String modelVersion,Long inferenceTimeMs){}
 @Transactional public RoadReport create(MultipartFile image,Double lat,Double lon,String note)throws IOException{
  if(image.isEmpty()||image.getSize()>10*1024*1024)throw new IllegalArgumentException("Image must be nonempty and at most 10 MB");String ct=image.getContentType();if(ct==null||!List.of("image/jpeg","image/png","image/webp").contains(ct))throw new IllegalArgumentException("Only JPEG, PNG, or WebP images are accepted");
  String ext=ct.equals("image/png")?".png":ct.equals("image/webp")?".webp":".jpg";String imageUrl=storage.store(image,ext);
  MlResult result=null;try{org.springframework.util.LinkedMultiValueMap<String,Object> payload=new org.springframework.util.LinkedMultiValueMap<>();payload.add("file",new org.springframework.core.io.ByteArrayResource(image.getBytes()){@Override public String getFilename(){return imageUrl.substring(imageUrl.lastIndexOf('/')+1);}});result=ml.post().uri("/detect").contentType(org.springframework.http.MediaType.MULTIPART_FORM_DATA).body(payload).retrieve().body(MlResult.class);}catch(Exception ignored){}
  RoadReport r=new RoadReport();r.imageUrl=imageUrl;r.latitude=lat;r.longitude=lon;r.note=note;if(result!=null&&result.detections()!=null&&!result.detections().isEmpty()){Detection d=result.detections().stream().max(Comparator.comparingDouble(Detection::confidence)).orElseThrow();r.detectedDamageType=d.type();r.aiConfidence=d.confidence();r.status=ReportStatus.AI_FLAGGED;}
  reports.save(r);if(lat!=null&&lon!=null){RoadIssue nearby=issues.findAll().stream().filter(i->distance(lat,lon,i.latitude,i.longitude)<=radius).min(Comparator.comparingDouble(i->distance(lat,lon,i.latitude,i.longitude))).orElse(null);if(nearby==null){nearby=new RoadIssue();nearby.latitude=lat;nearby.longitude=lon;nearby.damageType=r.detectedDamageType==null?"unclassified":r.detectedDamageType;nearby.title="Road damage report";issues.save(nearby);}else{nearby.reportCount++;nearby.updatedAt=Instant.now();issues.save(nearby);}r.issueId=nearby.id;reports.save(r);}
  AuditEvent e=new AuditEvent();e.reportId=r.id;e.action="REPORT_SUBMITTED";e.details="Citizen report submitted; AI output is a suggestion requiring human review.";audits.save(e);return r;
 }
 public static double distance(double a,double b,double c,double d){double p=Math.PI/180,x=(c-a)*p,y=(d-b)*p;double h=Math.sin(x/2)*Math.sin(x/2)+Math.cos(a*p)*Math.cos(c*p)*Math.sin(y/2)*Math.sin(y/2);return 6371000*2*Math.atan2(Math.sqrt(h),Math.sqrt(1-h));}
 @Transactional public RoadReport setStatus(Long id,ReportStatus status){RoadReport r=reports.findById(id).orElseThrow(()->new NoSuchElementException("Report not found"));ReportStatus old=r.status;r.status=status;r.updatedAt=Instant.now();reports.save(r);AuditEvent e=new AuditEvent();e.reportId=id;e.action="STATUS_CHANGED";e.details=old+" -> "+status;audits.save(e);return r;}
}
